sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.showClarificationBox = false;
    c.clarifyingPost = null;
    c.clarificationText = '';
    c.submitting = false;


    /*
     * ==========================================
     * OPEN MENTOR CONNECT RECORD PRODUCER
     * ==========================================
     */

    c.openPostProducer = function() {

        window.location.href =
            '?id=sc_cat_item&sys_id=816c7ca814e303107f4482b2cd248332';

    };


    /*
     * ==========================================
     * OPEN CLARIFICATION MODAL
     * ==========================================
     */

    c.clarifyDoubt = function(post) {

        if (!post) {
            return;
        }

        /*
         * Do not allow clarification of an
         * already resolved doubt.
         */

        if (post.resolved_clarified) {
            return;
        }

        c.clarifyingPost = post;
        c.clarificationText = '';
        c.showClarificationBox = true;

    };


    /*
     * ==========================================
     * CANCEL CLARIFICATION
     * ==========================================
     */

    c.cancelClarification = function() {

        if (c.submitting) {
            return;
        }

        c.showClarificationBox = false;
        c.clarifyingPost = null;
        c.clarificationText = '';
        c.submitting = false;

    };


    /*
     * ==========================================
     * SUBMIT CLARIFICATION
     * ==========================================
     */

    c.submitClarification = function() {

        if (c.submitting) {
            return;
        }


        /*
         * Check selected doubt
         */

        if (!c.clarifyingPost) {

            alert(
                'Unable to identify the selected doubt.'
            );

            return;
        }


        /*
         * Check clarification text
         */

        if (
            !c.clarificationText ||
            !c.clarificationText.trim()
        ) {

            alert(
                'Please enter a clarification.'
            );

            return;
        }


        /*
         * Check minimum length
         */

        if (c.clarificationText.trim().length < 5) {

            alert(
                'Please provide a meaningful clarification.'
            );

            return;
        }


        /*
         * Check record ID
         */

        if (!c.clarifyingPost.sys_id) {

            alert(
                'Doubt record ID is missing.'
            );

            return;
        }


        c.submitting = true;


        /*
         * Send clarification to Server Script
         */

        c.server.get({

            action: 'clarify_doubt',

            postId:
                c.clarifyingPost.sys_id,

            clarification:
                c.clarificationText.trim()

        }).then(function(response) {

            var result =
                response.data || {};


            /*
             * Stop submitting state
             */

            c.submitting = false;


            /*
             * ======================================
             * SUCCESS
             * ======================================
             */

            if (result.success === true) {

                alert(
                    'Doubt clarified successfully.'
                );


                /*
                 * Remove the old unresolved copy
                 * from the current list.
                 *
                 * The server refresh below will then
                 * bring it back as a resolved doubt
                 * with clarification information.
                 */

                if (
                    c.data &&
                    c.data.posts &&
                    c.clarifyingPost &&
                    c.clarifyingPost.sys_id
                ) {

                    for (
                        var i = 0;
                        i < c.data.posts.length;
                        i++
                    ) {

                        if (
                            c.data.posts[i].sys_id ===
                            c.clarifyingPost.sys_id
                        ) {

                            c.data.posts.splice(i, 1);

                            break;
                        }
                    }
                }


                /*
                 * Close clarification modal
                 */

                c.showClarificationBox = false;

                c.clarifyingPost = null;

                c.clarificationText = '';


                /*
                 * Refresh server data.
                 *
                 * The resolved doubt will now appear
                 * with:
                 *
                 * Question
                 * Answer
                 * Clarified By
                 * College
                 */

                c.server.update();


            } else {

                alert(
                    result.message ||
                    'Unable to clarify the doubt.'
                );

            }

        }, function(error) {

            c.submitting = false;

            console.log(
                'Clarification server error:',
                error
            );

            alert(
                'Unable to submit the clarification. Please try again.'
            );

        });

    };

};

sp_widget.css:
/* ==========================================
   POST MENTOR TIP / DOUBT BUTTON
   ========================================== */

.mentor-post-button {
    margin-top: 18px;
    padding: 11px 20px;
    border: none;
    border-radius: 8px;
    background: #0b63ce;
    color: #ffffff;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

.mentor-post-button:hover {
    background: #084f9f;
    transform: translateY(-1px);
}

.mentor-post-button:focus {
    outline: none;
    box-shadow: 0 0 0 3px rgba(11, 99, 206, 0.18);
}


/* ==========================================
   CAMPUS CONNECT - MENTOR CONNECT
   ========================================== */

.mentor-connect-page {
    width: 140%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 10px 40px 40px 200px;
    font-family: "Source Sans Pro", Arial, sans-serif;
}


/* ==========================================
   HEADER
   ========================================== */

.mentor-header {
    margin-bottom: 28px;
}

.mentor-eyebrow {
    color: #0066d6;
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 1.4px;
    text-transform: uppercase;
    margin-bottom: 6px;
}

.mentor-title {
    margin: 0 0 8px 0;
    color: #07152f;
    font-size: 38px;
    font-weight: 700;
    line-height: 1.15;
}

.mentor-subtitle {
    margin: 0;
    color: #536987;
    font-size: 17px;
    line-height: 1.5;
}


/* ==========================================
   CARD GRID
   ========================================== */

.mentor-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 18px;
}


/* ==========================================
   MENTOR CARD
   ========================================== */

.mentor-card {
    position: relative;
    background: #ffffff;
    border: 1px solid #d4dfed;
    border-radius: 10px;
    padding: 24px 18px 20px;
    min-height: 390px;

    box-shadow: 0 2px 8px rgba(7, 21, 47, 0.06);

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}

.mentor-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 7px 18px rgba(7, 21, 47, 0.12);
}


/* ==========================================
   AVATAR
   ========================================== */

.mentor-avatar {
    width: 72px;
    height: 72px;

    display: flex;
    align-items: center;
    justify-content: center;

    margin-bottom: 18px;

    border-radius: 50%;

    background: #e1efff;
    color: #0066d6;

    font-size: 24px;
    font-weight: 700;
}


/* ==========================================
   AUTHOR
   ========================================== */

.mentor-author {
    color: #07152f;
    font-size: 19px;
    font-weight: 700;
    margin-bottom: 7px;
}


/* ==========================================
   POST TYPE
   ========================================== */

.mentor-post-type {
    color: #0066d6;
    font-size: 13px;
    font-weight: 700;
    margin-bottom: 12px;
}


/* ==========================================
   DOMAIN TAG
   ========================================== */

.mentor-domain {
    display: inline-block;

    background: #edf4fb;
    color: #536987;

    border-radius: 18px;

    padding: 5px 11px;

    font-size: 12px;
    font-weight: 600;

    margin-bottom: 16px;
}


/* ==========================================
   CONTENT
   ========================================== */

.mentor-content {
    color: #536987;
    font-size: 14px;
    line-height: 1.6;

    margin-bottom: 16px;

    min-height: 70px;

    white-space: pre-line;
}


/* ==========================================
   RELATED EVENT
   ========================================== */

.mentor-event {
    color: #07152f;
    font-size: 12px;
    line-height: 1.5;

    margin-bottom: 18px;
}

.mentor-event strong {
    font-weight: 700;
}


/* ==========================================
   CLARIFY BUTTON
   ========================================== */

.mentor-clarify-button {
    width: 100%;

    border: none;
    border-radius: 7px;

    padding: 11px 14px;

    background: #0066d6;
    color: #ffffff;

    font-size: 14px;
    font-weight: 700;

    cursor: pointer;

    transition:
        background 0.2s ease,
        box-shadow 0.2s ease;
}

.mentor-clarify-button:hover {
    background: #0057b8;
    box-shadow: 0 4px 10px rgba(0, 102, 214, 0.22);
}

.mentor-clarify-button:focus {
    outline: none;
}

.mentor-clarify-button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}


/* ==========================================
   EMPTY STATE
   ========================================== */

.mentor-empty {
    background: #ffffff;
    border: 1px solid #d4dfed;
    border-radius: 10px;

    padding: 50px 25px;

    text-align: center;

    box-shadow: 0 2px 8px rgba(7, 21, 47, 0.05);
}

.mentor-empty-icon {
    font-size: 40px;
    margin-bottom: 12px;
}

.mentor-empty h3 {
    color: #07152f;
    font-size: 20px;
    font-weight: 700;
    margin: 0 0 7px;
}

.mentor-empty p {
    color: #536987;
    font-size: 14px;
    margin: 0;
}


/* ==========================================
   RESPONSIVE
   ========================================== */

@media (max-width: 1200px) {

    .mentor-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }

}

@media (max-width: 900px) {

    .mentor-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

}

@media (max-width: 600px) {

    .mentor-connect-page {
        padding: 5px 10px 30px;
    }

    .mentor-title {
        font-size: 30px;
    }

    .mentor-grid {
        grid-template-columns: 1fr;
    }

    .mentor-card {
        min-height: auto;
    }

}


/* ==========================================
   CLARIFICATION MODAL
   ========================================== */

.clarification-overlay {
    position: fixed;
    top: 0;
    left: 0;

    width: 100%;
    height: 100%;

    background: rgba(7, 21, 47, 0.55);

    display: flex;
    align-items: center;
    justify-content: center;

    padding: 20px;

    z-index: 9999;
}


.clarification-modal {
    width: 100%;
    max-width: 620px;

    background: #ffffff;

    border-radius: 12px;

    box-shadow: 0 15px 45px rgba(7, 21, 47, 0.25);

    overflow: hidden;
}


/* ---------- Header ---------- */

.clarification-modal-header {
    display: flex;

    justify-content: space-between;
    align-items: flex-start;

    padding: 22px 24px;

    border-bottom: 1px solid #e1e8f0;

    background: #f8fbff;
}


.clarification-label {
    color: #0066d6;

    font-size: 11px;

    font-weight: 700;

    letter-spacing: 1.3px;

    text-transform: uppercase;

    margin-bottom: 5px;
}


.clarification-modal-header h3 {
    margin: 0;

    color: #07152f;

    font-size: 23px;

    font-weight: 700;
}


.clarification-close {
    border: none;

    background: transparent;

    color: #536987;

    font-size: 28px;

    line-height: 1;

    cursor: pointer;

    padding: 0 4px;
}


.clarification-close:hover {
    color: #07152f;
}


/* ---------- Body ---------- */

.clarification-modal-body {
    padding: 24px;
}


.clarification-doubt {
    background: #f4f8fd;

    border-left: 4px solid #0066d6;

    border-radius: 6px;

    padding: 15px 17px;

    margin-bottom: 22px;
}


.clarification-doubt-label {
    color: #0066d6;

    font-size: 11px;

    font-weight: 700;

    text-transform: uppercase;

    letter-spacing: 0.7px;

    margin-bottom: 7px;
}


.clarification-doubt strong {
    display: block;

    color: #07152f;

    font-size: 14px;

    margin-bottom: 6px;
}


.clarification-doubt p {
    margin: 0;

    color: #536987;

    font-size: 14px;

    line-height: 1.6;
}


/* ---------- Input ---------- */

.clarification-input-label {
    display: block;

    color: #07152f;

    font-size: 14px;

    font-weight: 700;

    margin-bottom: 8px;
}


.clarification-textarea {
    width: 100%;

    min-height: 130px;

    resize: vertical;

    border: 1px solid #cbd7e5;

    border-radius: 7px;

    padding: 12px 14px;

    color: #34465d;

    font-size: 14px;

    line-height: 1.6;

    outline: none;
}


.clarification-textarea:focus {
    border-color: #0066d6;

    box-shadow: 0 0 0 2px rgba(0, 102, 214, 0.10);
}


/* ---------- Footer ---------- */

.clarification-modal-footer {
    display: flex;

    justify-content: flex-end;

    gap: 10px;

    padding: 16px 24px;

    border-top: 1px solid #e1e8f0;

    background: #ffffff;
}


.clarification-cancel {
    border: 1px solid #cbd7e5;

    background: #ffffff;

    color: #536987;

    border-radius: 7px;

    padding: 9px 18px;

    font-size: 14px;

    font-weight: 600;

    cursor: pointer;
}


.clarification-cancel:hover {
    background: #f4f7fa;
}


.clarification-submit {
    border: none;

    background: #0066d6;

    color: #ffffff;

    border-radius: 7px;

    padding: 9px 18px;

    font-size: 14px;

    font-weight: 700;

    cursor: pointer;
}


.clarification-submit:hover {
    background: #0057b8;
}


.clarification-submit:disabled {
    opacity: 0.6;

    cursor: not-allowed;
}


/* ---------- Mobile ---------- */

@media (max-width: 600px) {

    .clarification-overlay {
        padding: 12px;
    }

    .clarification-modal-body {
        padding: 18px;
    }

    .clarification-modal-header {
        padding: 18px;
    }

    .clarification-modal-footer {
        padding: 14px 18px;
    }

}

sp_widget.script:
(function() {

    data.posts = [];
    data.success = false;
    data.message = '';


    /*
     * ==========================================
     * CLARIFY NEWCOMER DOUBT
     * ==========================================
     */

    if (input && input.action == 'clarify_doubt') {

        var postId = String(input.postId || '');
        var clarification = String(input.clarification || '').trim();

        if (!postId) {
            data.message = 'Doubt information is missing.';
            return;
        }

        if (!clarification) {
            data.message = 'Please enter a clarification.';
            return;
        }

        var doubt = new GlideRecord(
            'x_snc_campus_con_0_mentor_connect'
        );

        if (!doubt.get(postId)) {
            data.message = 'The selected doubt was not found.';
            return;
        }


        /*
         * Check the DISPLAY value of Post Type.
         */

        var postTypeDisplay = String(
            doubt.getDisplayValue('post_type') || ''
        ).trim().toLowerCase();

        var postTypeValue = String(
            doubt.getValue('post_type') || ''
        ).trim().toLowerCase();

        if (
            postTypeDisplay != 'newcomer doubt' &&
            postTypeValue != 'newcomer_doubt' &&
            postTypeValue != 'newcomer doubt'
        ) {
            data.message = 'Only Newcomer Doubts can be clarified.';
            return;
        }


        /*
         * Check whether already clarified.
         */

        var resolvedValue = String(
            doubt.getValue('resolved_clarified') || ''
        ).toLowerCase();

        if (
            resolvedValue == '1' ||
            resolvedValue == 'true' ||
            resolvedValue == 'yes'
        ) {
            data.message = 'This doubt has already been clarified.';
            return;
        }


        /*
         * Save clarification.
         */

        doubt.setValue(
            'clarification',
            clarification
        );

        doubt.setValue(
            'resolved_clarified',
            true
        );


        /*
         * The update is performed by the currently
         * logged-in student.
         *
         * ServiceNow will automatically update
         * sys_updated_by with that student's
         * user_name.
         */

        var updatedId = doubt.update();

        if (!updatedId) {
            data.message = 'Unable to save the clarification.';
            return;
        }

        data.success = true;
        data.message = 'Doubt clarified successfully.';

        return;
    }


    /*
     * ==========================================
     * LOAD MENTOR CONNECT POSTS
     * ==========================================
     *
     * Existing unresolved posts remain visible.
     *
     * Additionally, resolved Newcomer Doubts
     * are loaded so the question + answer +
     * clarifier details can be displayed.
     */

    var gr = new GlideRecord(
        'x_snc_campus_con_0_mentor_connect'
    );

    gr.orderByDesc('sys_created_on');
    gr.query();


    while (gr.next()) {

        var post = {};

        post.sys_id = gr.getUniqueValue();

        post.author =
            gr.getDisplayValue('author');

        post.content =
            gr.getValue('content');

        post.domain_tag =
            gr.getValue('domain_tag');


        /*
         * Keep display value for UI.
         */

        post.post_type =
            gr.getDisplayValue('post_type');


        /*
         * Reliable Newcomer Doubt check.
         */

        var displayType = String(
            gr.getDisplayValue('post_type') || ''
        ).trim().toLowerCase();

        var storedType = String(
            gr.getValue('post_type') || ''
        ).trim().toLowerCase();

        post.is_newcomer_doubt =
            displayType == 'newcomer doubt' ||
            storedType == 'newcomer_doubt' ||
            storedType == 'newcomer doubt';


        post.related_event =
            gr.getDisplayValue('related_event');


        /*
         * Get resolved status.
         */

        var resolvedRaw = String(
            gr.getValue('resolved_clarified') || ''
        ).toLowerCase();

        post.resolved_clarified =
            resolvedRaw == '1' ||
            resolvedRaw == 'true' ||
            resolvedRaw == 'yes';


        /*
         * ==========================================
         * CLARIFICATION DETAILS
         * ==========================================
         */

        post.clarification =
            gr.getValue('clarification') || '';

        post.clarified_by = '';
        post.clarifier_college = '';


        /*
         * Only fetch clarifier information when
         * this is a resolved Newcomer Doubt.
         */

        if (
            post.is_newcomer_doubt &&
            post.resolved_clarified &&
            post.clarification
        ) {

            /*
             * sys_updated_by contains the user_name
             * of the student who submitted the
             * clarification.
             */

            var clarifierUserName = String(
                gr.getValue('sys_updated_by') || ''
            ).trim();


            if (clarifierUserName) {

                /*
                 * Find the corresponding sys_user.
                 */

                var clarifierUser =
                    new GlideRecord('sys_user');

                clarifierUser.addQuery(
                    'user_name',
                    clarifierUserName
                );

                clarifierUser.setLimit(1);
                clarifierUser.query();


                if (clarifierUser.next()) {

                    /*
                     * Student name
                     */

                    clarifierUserName =
                        clarifierUser.getDisplayValue();


                    post.clarified_by =
                        clarifierUserName;


                    /*
                     * Find Student Profile
                     * belonging to this student.
                     */

                    var clarifierProfile =
                        new GlideRecord(
                            'x_snc_campus_con_0_student_profile'
                        );

                    clarifierProfile.addQuery(
                        'student',
                        clarifierUser.getUniqueValue()
                    );

                    clarifierProfile.setLimit(1);
                    clarifierProfile.query();


                    if (clarifierProfile.next()) {

                        post.clarifier_college =
                            clarifierProfile.getValue(
                                'college_name'
                            ) || '';

                    }

                }

            }

        }


        /*
         * ==========================================
         * IMPORTANT:
         * ==========================================
         *
         * Show:
         *
         * 1. All unresolved posts
         * 2. Resolved Newcomer Doubts
         *
         * Other resolved mentor posts continue
         * to remain hidden as before.
         */

        if (
            !post.resolved_clarified ||
            (
                post.is_newcomer_doubt &&
                post.resolved_clarified
            )
        ) {

            data.posts.push(post);

        }

    }

})();
